    search: '<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>'
  } as const;
  export type IconName = keyof typeof P;
  /** Whether the set draws `name` (a packing category's own emoji, say, is not a name). */
  export const isIcon = (name: string): name is IconName => Object.hasOwn(P, name);

  /** A drawing's shapes (path / circle / rect and their attributes), parsed once a name: no {@html}. `closed`: a shape
   *  the soft fill goes in (a rect, a circle bigger than a dot, a path that ends closed). */
  type Shape = { tag: 'path' | 'circle' | 'rect'; a: Record<string, string>; closed: boolean };
  const parsed = new Map<IconName, Shape[]>();
  function shapes(n: IconName): Shape[] {
    let s = parsed.get(n);
    if (!s) {
      s = [...P[n].matchAll(/<(path|circle|rect)\s([^>]*?)\/>/g)].map((m) => {
        const a = Object.fromEntries([...m[2].matchAll(/([\w-]+)="([^"]*)"/g)].map((x) => [x[1], x[2]]));
        const tag = m[1] as Shape['tag'];
        return { tag, a, closed: tag === 'rect' || (tag === 'circle' ? Number(a.r) >= 2 : /z\s*$/i.test(a.d)) };
      });
      parsed.set(n, s);
    }
    return s;
  }
</script>

<script lang="ts">
  interface Props {
    /** An IconName; any other string draws the pin. */
    name: IconName | (string & {});
    /** px, square (default 20). A parent's CSS on `.ic` wins over it. */
    size?: number;
    /** The stroke width (default 2; the tick inside a filled circle 2.6). */
    stroke?: number;
    /** The soft fill inside closed shapes. */
    soft?: boolean;
  }
  let { name, size = 20, stroke = 2, soft = false }: Props = $props();
  const body = $derived(shapes(isIcon(name) ? name : 'pin'));
</script>

<svg class="ic" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
  stroke-width={stroke} stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  {#each body as s, i (i)}
    {@const f = soft && s.closed ? 'color-mix(in srgb, currentColor 18%, transparent)' : undefined}
    {#if s.tag === 'path'}<path d={s.a.d} style:fill={f} />{:else if s.tag === 'circle'}<circle cx={s.a.cx} cy={s.a.cy} r={s.a.r} style:fill={f} />{:else}<rect x={s.a.x} y={s.a.y} width={s.a.width} height={s.a.height} rx={s.a.rx} style:fill={f} />{/if}
  {/each}
</svg>

<style>
  .ic { flex: none; display: inline-block; vertical-align: middle; }
</style>
